const body = $input.first().json.body || $input.first().json;

const eventName = body.event || body.event_name || 'messages.upsert';
const instance = body.instance || body.instance_name;
const dataObj = body.data || body.payload || body;

// Filtro de evento
if (eventName !== 'messages.upsert' && eventName !== 'MESSAGES_UPSERT') {
  return [{
    json: {
      is_valid: false,
      reason: "IGNORED_EVENT",
      status: "ignored",
      message: `Evento '${eventName}' ignorado`,
      timestamp: new Date().toISOString()
    }
  }];
}

// Filtro de mensagens próprias (fromMe = true)
const key = dataObj.key || {};
if (key.fromMe === true) {
  return [{
    json: {
      is_valid: false,
      reason: "OUTBOUND_SELF_MESSAGE",
      status: "ignored",
      message: "Mensagem enviada pela própria empresa ignorada no fluxo inbound",
      timestamp: new Date().toISOString()
    }
  }];
}

// Validação de campos obrigatórios
const remoteJid = key.remoteJid || dataObj.sender;
const messageId = key.id || dataObj.id;

if (!instance || !remoteJid || !messageId) {
  return [{
    json: {
      is_valid: false,
      reason: "VALIDATION_ERROR",
      status: "validation_error",
      message: "Campos obrigatórios ausentes: instance, remoteJid ou message_id",
      timestamp: new Date().toISOString()
    }
  }];
}

const cleanPhone = remoteJid.replace(/@.*$/, '').replace(/[^0-9]/g, '');
const formattedPhone = cleanPhone ? '+' + cleanPhone : null;

if (!formattedPhone) {
  return [{
    json: {
      is_valid: false,
      reason: "VALIDATION_ERROR",
      status: "validation_error",
      message: "Número de telefone do contato inválido",
      timestamp: new Date().toISOString()
    }
  }];
}

const messageType = dataObj.messageType || 'text';
const textContent = (dataObj.message && (dataObj.message.conversation || dataObj.message.extendedTextMessage?.text)) || dataObj.content || '';
const pushName = dataObj.pushName || dataObj.sender_name || null;

return [{
  json: {
    is_valid: true,
    instance: String(instance).trim(),
    external_message_id: String(messageId).trim(),
    phone: formattedPhone,
    push_name: pushName,
    message_type: messageType,
    content: textContent,
    raw_event: JSON.stringify({ instance, event: eventName, messageId })
  }
}];

const items = $input.all();
const first = items[0];
const prevData = $('1. Validar e Filtrar Inbound').first().json;

if (first.error || items.length === 0 || !first.json || !first.json.tenant_id) {
  return [{
    json: {
      resolved: false,
      status: "tenant_not_resolved",
      code: "TENANT_NOT_RESOLVED",
      message: `Nenhum tenant/canal ativo associado à instância '${prevData.instance}'`,
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    resolved: true,
    tenant_id: first.json.tenant_id,
    channel_id: first.json.channel_id,
    phone: prevData.phone,
    push_name: prevData.push_name,
    external_message_id: prevData.external_message_id,
    message_type: prevData.message_type,
    content: prevData.content,
    raw_event: prevData.raw_event
  }
}];

const tenantId = $('3. Checar Tenant Resolvido').first().json.tenant_id;
const channelId = $('3. Checar Tenant Resolvido').first().json.channel_id;
const contactId = $('4. Resolver / Criar Contact').first().json.contact_id;
const conversationId = $('5. Resolver / Criar Conversation').first().json.conversation_id;
const messageId = $('7. Persistir Message').first().json.message_id;
const content = $('3. Checar Tenant Resolvido').first().json.content;
const messageType = $('3. Checar Tenant Resolvido').first().json.message_type;

// Contexto Estruturado para o Supervisor IA (Fase Futura)
const aiContext = {
  tenant_id: tenantId,
  channel_id: channelId,
  contact_id: contactId,
  conversation_id: conversationId,
  message_id: messageId,
  message_type: messageType,
  message_text: content,
  direction: "inbound"
};

return [{
  json: {
    success: true,
    status: "processed",
    code: "MESSAGE_PROCESSED",
    message: "Mensagem inbound processada e gravada no PostgreSQL",
    ai_context: aiContext,
    timestamp: new Date().toISOString()
  }
}];
